// Parse Firebase config and calculate rotation
const response = $input.first().json;
const fields = response.fields;

// Helper: parse Firebase value
function fbVal(v) {
  if (!v) return null;
  if (v.stringValue !== undefined) return v.stringValue;
  if (v.integerValue !== undefined) return parseInt(v.integerValue);
  if (v.mapValue) {
    const obj = {};
    const f = v.mapValue.fields;
    for (const k in f) obj[k] = fbVal(f[k]);
    return obj;
  }
  if (v.arrayValue) {
    return (v.arrayValue.values || []).map(fbVal);
  }
  return null;
}

const config = {};
for (const k in fields) config[k] = fbVal(fields[k]);

const now = new Date();
const year = now.getFullYear();
const month = now.getMonth(); // 0-indexed

// Calculate second Thursday (deadline)
const first = new Date(year, month, 1);
const firstDay = first.getDay();
const firstThursday = 1 + ((4 - firstDay + 7) % 7);
const deadline = firstThursday + 7;
const dayNames = ['일','월','화','수','목','금','토'];
const deadlineDate = new Date(year, month, deadline);
const deadlineStr = `${month+1}월 ${deadline}일(${dayNames[deadlineDate.getDay()]}) 오후 2시`;

const results = [];

['2F', '3F'].forEach(floor => {
  const f = config.floors ? config.floors[floor] : null;
  if (!f) return;

  const teams = f.teams || [];
  if (teams.length === 0) return;

  const startParts = (f.startMonth || '2026-03').split('-');
  const startYear = parseInt(startParts[0]);
  const startMonth = parseInt(startParts[1]) - 1;
  const startIndex = f.startIndex || 0;

  const monthsDiff = (year - startYear) * 12 + (month - startMonth);
  const idx = ((startIndex + monthsDiff) % teams.length + teams.length) % teams.length;
  const teamName = teams[idx];
  const contact = f.contacts ? f.contacts[teamName] : null;

  const budgetKey = floor === '2F' ? '석민이앤씨' : '넷폼알앤디';
  const budget = config.budget ? (config.budget[budgetKey] || 500000) : 500000;

  results.push({
    floor: floor,
    team: teamName,
    name: contact ? contact.name : '',
    email: contact ? contact.email : '',
    month: month + 1,
    year: year,
    monthKey: `${year}-${String(month+1).padStart(2,'0')}`,
    deadline: deadlineStr,
    budget: budget.toLocaleString()
  });
});

return results;
